import json
from pathlib import Path


FRAGMENTS = [
    ["44-quindecies.xml"],
    ["44-quindecies-A-partie-1.xml", "44-quindecies-A-partie-2.xml"],
    ["44-sexdecies.xml"],
    ["44-septdecies.xml"],
    ["45.xml"],
]

